arguments.file_text:
@page "/chat"
@using sv_4194526744a848339c7a3d6618d19a32.Models
@using sv_4194526744a848339c7a3d6618d19a32.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_isThreadOpen ? "" : "chat-main-full")">
        <MessagePanel Channel="_activeChannel"
                      Messages="_messages"
                      ThreadReplyCounts="_threadReplyCounts"
                      IsLoadingMore="_isLoadingMore"
                      OnOpenThread="OpenThread"
                      OnReact="HandleReaction"
                      OnSendMessage="SendMessage"
                      OnLoadOlderMessages="LoadOlderMessages" />
    </div>

    @if (_isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = [];

    private int _activeChannelId;
    private Channel? _activeChannel;
    private bool _isLoadingMore;

    // Thread state
    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await BuildThreadReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task BuildThreadReplyCounts()
    {
        _threadReplyCounts = [];
        // Identify root messages that have replies (messages where other messages reference them)
        var rootIds = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        foreach (var rootId in rootIds)
        {
            var thread = await ChatService.GetThreadAsync(rootId);
            if (thread.Count > 0)
            {
                _threadReplyCounts[rootId] = thread.Count;
            }
        }
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(sent);
    }

    private async Task OpenThread(int messageId)
    {
        var rootMsg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (rootMsg is null) return;

        _threadRootMessage = rootMsg;
        _threadMessages = await ChatService.GetThreadAsync(messageId);
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            _activeChannelId, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistically update the local message
        var idx = _messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = _messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("You"))
                {
                    reactions[existing] = r with { Users = [..r.Users, "You"] };
                }
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            _messages[idx] = msg with { Reactions = reactions };
        }
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore) return;

        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(
            _activeChannelId, _messages.Count, PageSize);

        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
        }

        _isLoadingMore = false;
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    width: 55%;
    flex: 1;
    min-width: 0;
}

.chat-main-full {
    width: 80%;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

@page "/chat"
